CREATE COLUMN TABLE "TEST_AP"."OSRL" ("ItemCode" NVARCHAR(50) NOT NULL , "SerialNum" NVARCHAR(17) NOT NULL , "CardCode" NVARCHAR(15), "DocNum" INTEGER CS_INT, "UserSign" SMALLINT CS_INT, PRIMARY KEY ("ItemCode", "SerialNum")) UNLOAD PRIORITY 5  AUTO MERGE ;
ALTER TABLE "TEST_AP"."OSRL" WITH PARAMETERS ('CONCAT_ATTRIBUTE'=('$DocNum$ItemCode$','DocNum','ItemCode'));
CREATE INDEX "OSRL_INV_NUM" ON "TEST_AP"."OSRL" ( "DocNum" ASC, "ItemCode" ASC );
CREATE INDEX "OSRL_CARD_KEY" ON "TEST_AP"."OSRL" ( "CardCode" ASC )